-- 599: Original BrillaPrep Cambridge IGCSE Chemistry (0620) sprint 3 beta questions, part 6 of 13 (batch igcse-chemistry-sprint3-001).
-- Curriculum-aligned practice content; not official Cambridge International, WAEC or NSMQ examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_599_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_599_guard;
INSERT INTO _migration_599_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_021' AND NOT (q.topic_id IS 'topic_igcse_chem_acids' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which ion is responsible for the acidic properties of aqueous solutions of acids?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The hydroxide ion, OH⁻(aq)","B. The hydrogen ion, H⁺(aq)","C. The oxide ion, O²⁻","D. The hydronium-free metal cation"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Acids produce hydrogen ions, H⁺(aq), in aqueous solution, and it is these ions that give acids their characteristic reactions. (OH⁻ is responsible for alkaline behaviour; oxide ions act as bases.) Therefore the correct answer is B: The hydrogen ion, H⁺(aq).' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_021' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_599_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_022' AND NOT (q.topic_id IS 'topic_igcse_chem_acids' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What colour is universal indicator in a solution of pH 2?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Green","B. Purple","C. Red","D. Blue"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Universal indicator is red in strongly acidic solutions (pH 1–2). (Green indicates a neutral solution of pH 7; blue and purple indicate increasingly alkaline solutions.) Therefore the correct answer is C: Red.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_022' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_599_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_023' AND NOT (q.topic_id IS 'topic_igcse_chem_acids' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which type of reaction takes place when dilute hydrochloric acid reacts with aqueous sodium hydroxide?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Oxidation","B. Thermal decomposition","C. Displacement","D. Neutralisation"]' AND q.correct_answer IS 'D' AND q.explanation IS 'An acid reacting with an alkali (a soluble base) to form a salt and water is a neutralisation: HCl + NaOH → NaCl + H₂O. (No element changes oxidation state, nothing is broken down by heat, and no element displaces another.) Therefore the correct answer is D: Neutralisation.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_023' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_599_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_024' AND NOT (q.topic_id IS 'topic_igcse_chem_acids' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Pure copper(II) sulfate crystals are prepared by adding excess copper(II) oxide to warm dilute sulfuric acid, filtering and crystallising the filtrate. Why is the copper(II) oxide added in excess?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. To make sure that all of the sulfuric acid has reacted.","B. To make the reaction go faster.","C. To act as a catalyst for the reaction.","D. To increase the amount of sulfuric acid available."]' AND q.correct_answer IS 'A' AND q.explanation IS 'Copper(II) oxide is insoluble, so any unreacted excess is simply removed by filtration; using an excess guarantees that no acid remains to contaminate the salt solution. (The oxide is a reactant, not a catalyst, and it cannot create more acid.) Therefore the correct answer is A: To make sure that all of the sulfuric acid has reacted..' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_024' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_021', 'topic_igcse_chem_acids', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'Which ion is responsible for the acidic properties of aqueous solutions of acids?', 'multiple_choice', NULL, '["A. The hydroxide ion, OH⁻(aq)","B. The hydrogen ion, H⁺(aq)","C. The oxide ion, O²⁻","D. The hydronium-free metal cation"]', 'B', 'Acids produce hydrogen ions, H⁺(aq), in aqueous solution, and it is these ions that give acids their characteristic reactions. (OH⁻ is responsible for alkaline behaviour; oxide ions act as bases.) Therefore the correct answer is B: The hydrogen ion, H⁺(aq).', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, 'board_cambridge');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_022', 'topic_igcse_chem_acids', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'What colour is universal indicator in a solution of pH 2?', 'multiple_choice', NULL, '["A. Green","B. Purple","C. Red","D. Blue"]', 'C', 'Universal indicator is red in strongly acidic solutions (pH 1–2). (Green indicates a neutral solution of pH 7; blue and purple indicate increasingly alkaline solutions.) Therefore the correct answer is C: Red.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, 'board_cambridge');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_023', 'topic_igcse_chem_acids', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'Which type of reaction takes place when dilute hydrochloric acid reacts with aqueous sodium hydroxide?', 'multiple_choice', NULL, '["A. Oxidation","B. Thermal decomposition","C. Displacement","D. Neutralisation"]', 'D', 'An acid reacting with an alkali (a soluble base) to form a salt and water is a neutralisation: HCl + NaOH → NaCl + H₂O. (No element changes oxidation state, nothing is broken down by heat, and no element displaces another.) Therefore the correct answer is D: Neutralisation.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_024', 'topic_igcse_chem_acids', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'Pure copper(II) sulfate crystals are prepared by adding excess copper(II) oxide to warm dilute sulfuric acid, filtering and crystallising the filtrate. Why is the copper(II) oxide added in excess?', 'multiple_choice', NULL, '["A. To make sure that all of the sulfuric acid has reacted.","B. To make the reaction go faster.","C. To act as a catalyst for the reaction.","D. To increase the amount of sulfuric acid available."]', 'A', 'Copper(II) oxide is insoluble, so any unreacted excess is simply removed by filtration; using an excess guarantees that no acid remains to contaminate the salt solution. (The oxide is a reactant, not a catalyst, and it cannot create more acid.) Therefore the correct answer is A: To make sure that all of the sulfuric acid has reacted..', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge');
